func testManutencaoToManyAddOpManVeiculoManutencaos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Manutencao
	var b, c, d, e VeiculoManutencao

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, manutencaoDBTypes, false, strmangle.SetComplement(manutencaoPrimaryKeyColumns, manutencaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*VeiculoManutencao{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, veiculoManutencaoDBTypes, false, strmangle.SetComplement(veiculoManutencaoPrimaryKeyColumns, veiculoManutencaoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*VeiculoManutencao{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddManVeiculoManutencaos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ManID != first.ManID {
			t.Error("foreign key was wrong value", a.ManID, first.ManID)
		}
		if a.ManID != second.ManID {
			t.Error("foreign key was wrong value", a.ManID, second.ManID)
		}

		if first.R.Man != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Man != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.ManVeiculoManutencaos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.ManVeiculoManutencaos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.ManVeiculoManutencaos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

